script:
(function () {
  'use strict';
  // Fixed-rate vs adjustable-rate mortgage comparison.
  //   Payment: M = B * i / (1 - (1 + i)^-n), i = rate / 12, n = months left (M = B / n at 0%).
  //   ARM: rate fixed for the initial period, then changes by the expected amount at each adjustment,
  //   limited by the first/periodic caps, the lifetime cap (initial + cap) and the floor; the payment is
  //   re-amortized over the months left at each adjustment. Worst case = full cap rise every time.
  //   Cost over the horizon = interest paid in those months (principal repaid + balance left always
  //   equals the loan, so interest is the true cost of each loan up to a sale or refinance).
  //   Break-even = first month the ARM's cumulative interest exceeds the fixed loan's.
  // Verified in Node (scratchpad tests/w2b): $300,000 for 30 yrs: fixed 6.5% = $1,896.20/mo and
  //   $130,529.88 interest over 84 months; ARM 5.75% = $1,750.72/mo and $116,831.68 interest over 84
  //   months with a 5/1 path of +0.25%/yr (both closed form: k*M - (L - balance_k), re-amortized at
  //   6% and 6.25%); ARM equal to the fixed rate with no change = same cost; ARM above fixed = Never;
  //   0% rates = $833.33/mo; no NaN/Infinity on blank or bad input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id) {
    var raw = String(el(id).value).trim();
    if (raw === '') return NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function payment(balance, annualPct, months) {
    if (months <= 0 || balance <= 0) return 0;
    var i = annualPct / 1200;
    if (i === 0) return balance / months;
    return balance * i / (1 - Math.pow(1 + i, -months));
  }

  function pct(v) { return (Math.round(v * 1000) / 1000) + '%'; }

  // A fixed loan is an ARM whose fixed period covers the whole term.
  function schedule(o) {
    var rate = o.rate, maxRate = o.rate + o.lifeCap, minRate = Math.min(o.floor, o.rate);
    var bal = o.loan, pay = payment(bal, rate, o.months), rows = [], adj = 0, cum = 0, maxPay = pay;
    for (var m = 1; m <= o.months; m++) {
      if (m > o.fixedMonths && (m - o.fixedMonths - 1) % o.every === 0) {
        var cap = adj === 0 ? o.firstCap : o.periodicCap;
        rate = Math.max(minRate, Math.min(maxRate, rate + Math.max(-cap, Math.min(cap, o.change))));
        rate = Math.round(rate * 100000) / 100000;
        pay = payment(bal, rate, o.months - m + 1);
        adj++;
        if (pay > maxPay) maxPay = pay;
      }
      var interest = bal * rate / 1200;
      var principal = m === o.months ? bal : Math.min(pay - interest, bal);
      bal -= principal;
      if (bal < 0.005) bal = 0;
      cum += interest;
      rows.push({ rate: rate, payment: principal + interest, balance: bal, cumInterest: cum });
    }
    return { first: payment(o.loan, o.rate, o.months), maxPay: maxPay, totalInterest: cum, rows: rows };
  }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function clearResults() {
    ['fxWinner', 'fxSaving', 'fxBreakeven', 'fxFixedPay', 'fxArmPay', 'fxArmMax', 'fxArmWorst', 'fxFixedHorizon',
     'fxArmHorizon', 'fxArmWorstHorizon', 'fxFixedTotal', 'fxArmTotal'].forEach(function (id) { setText(id, '–'); });
    setText('fxNote', '');
    el('fxSchedule').innerHTML = '';
  }

  function update() {
    var loan = read('fxLoan'), years = read('fxTerm'), horizon = read('fxHorizon'), fixedRate = read('fxFixedRate'),
        armRate = read('fxArmRate'), fixedYears = read('fxFixed'), every = parseInt(el('fxEvery').value, 10),
        change = read('fxChange'), firstCap = read('fxFirstCap'), periodicCap = read('fxPeriodicCap'),
        lifeCap = read('fxLifeCap'), floor = read('fxFloor');
    var msg = '';
    if (isNaN(loan) || loan <= 0) msg = 'Enter a loan amount greater than $0.';
    else if (isNaN(years) || years < 1 || years > 40 || years % 1 !== 0) msg = 'Enter a loan term of 1 to 40 whole years.';
    else if (isNaN(horizon) || horizon < 1 || horizon % 1 !== 0 || horizon > years) msg = 'Enter how many whole years you expect to keep the loan, up to the loan term.';
    else if (isNaN(fixedRate) || fixedRate < 0 || fixedRate > 30 || isNaN(armRate) || armRate < 0 || armRate > 30) msg = 'Enter interest rates from 0% to 30%.';
    else if (isNaN(fixedYears) || fixedYears < 1 || fixedYears % 1 !== 0 || fixedYears >= years) msg = 'Enter an ARM fixed-rate period of at least 1 whole year that is shorter than the loan term.';
    else if (isNaN(change) || change < -5 || change > 5) msg = 'Enter an expected change per adjustment from -5% to 5%.';
    else if ([firstCap, periodicCap, lifeCap].some(function (v) { return isNaN(v) || v < 0 || v > 15; })) msg = 'Enter rate caps from 0% to 15%.';
    else if (isNaN(floor) || floor < 0 || floor > 30) msg = 'Enter a rate floor from 0% to 30%.';
    var error = el('fxError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var months = years * 12, h = horizon * 12;
    var arm = { loan: loan, months: months, rate: armRate, fixedMonths: fixedYears * 12, every: every, change: change,
                firstCap: firstCap, periodicCap: periodicCap, lifeCap: lifeCap, floor: floor };
    var a = schedule(arm);
    arm.change = 100;
    var w = schedule(arm);
    var f = schedule({ loan: loan, months: months, rate: fixedRate, fixedMonths: months, every: 12, change: 0,
                       firstCap: 0, periodicCap: 0, lifeCap: 0, floor: 0 });

    var fixedH = f.rows[h - 1].cumInterest, armH = a.rows[h - 1].cumInterest, worstH = w.rows[h - 1].cumInterest;
    var diff = fixedH - armH;
    if (Math.abs(diff) < 0.005) { setText('fxWinner', 'Same cost'); setText('fxSaving', money.format(0)); }
    else { setText('fxWinner', diff > 0 ? 'Adjustable rate' : 'Fixed rate'); setText('fxSaving', money.format(Math.abs(diff))); }

    var cross = 0;
    for (var m = 0; m < months; m++) {
      if (a.rows[m].cumInterest > f.rows[m].cumInterest + 0.005) { cross = m + 1; break; }
    }
    if (cross === 1) setText('fxBreakeven', 'Never');
    else if (cross === 0) setText('fxBreakeven', 'The full term');
    else setText('fxBreakeven', duration(cross - 1));

    setText('fxFixedPay', money.format(f.first));
    setText('fxArmPay', money.format(a.first));
    setText('fxArmMax', money.format(a.maxPay));
    setText('fxArmWorst', money.format(w.maxPay));
    setText('fxFixedHorizon', money.format(fixedH));
    setText('fxArmHorizon', money.format(armH));
    setText('fxArmWorstHorizon', money.format(worstH));
    setText('fxFixedTotal', money.format(f.totalInterest));
    setText('fxArmTotal', money.format(a.totalInterest));
    setText('fxNote', worstH > fixedH + 0.005
      ? 'If the ARM rate rises as fast as its caps allow, it would cost ' + money.format(worstH - fixedH) + ' more in interest than the fixed loan over ' + horizon + (horizon === 1 ? ' year.' : ' years.')
      : 'Even if the ARM rate rises as fast as its caps allow, it costs no more interest than the fixed loan over ' + horizon + (horizon === 1 ? ' year.' : ' years.'));

    var html = [];
    for (var y = 1; y <= years; y++) {
      var fr = f.rows[y * 12 - 1], ar = a.rows[y * 12 - 1];
      html.push('<tr><td>' + y + '</td><td>' + money.format(fr.payment) + '</td><td>' + pct(ar.rate) + '</td><td>' +
        money.format(ar.payment) + '</td><td>' + money.format(fr.balance) + '</td><td>' + money.format(ar.balance) + '</td><td>' +
        money.format(fr.cumInterest - ar.cumInterest) + '</td></tr>');
    }
    el('fxSchedule').innerHTML = html.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('fxForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
